import{_ as s,o as a,c as n,a4 as t}from"./chunks/framework.B-wJupoK.js";const r="/assets/image-20260802121927583.9RwK3Io-.png",p="/assets/image-20260802121702176.C7SmPOZ0.png",o="/assets/image-20260802121743303.BpvLzEeT.png",l="/assets/image-20260802121803412.B18sdNx1.png",h="/assets/image-20260802122148009.DlDUwQkk.png",i="/assets/image-20260802122209852.B9533ANI.png",g="/assets/image-20260802120234453.DYBYAXsv.png",_="/assets/image-20260802120257143.BFGhZ0Rn.png",I=JSON.parse('{"title":"DeepSeek-V4-Flash 正式版上线了，但这 3 个坑我帮你提前踩了","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/DeepSeek-V4-Flash 正式版上线了，但这 3 个坑我帮你提前踩了/DeepSeek-V4-Flash 正式版上线了，但这 3 个坑我帮你提前踩了.md","filePath":"AI人工智能/DeepSeek-V4-Flash 正式版上线了，但这 3 个坑我帮你提前踩了/DeepSeek-V4-Flash 正式版上线了，但这 3 个坑我帮你提前踩了.md","lastUpdated":1785645620000,"__rawMarkdown":"# DeepSeek-V4-Flash 正式版上线了，但这 3 个坑我帮你提前踩了\\n\\n## 前言\\n\\n**DeepSeek-V4-Flash 正式版**的 API 已于 **7 月 31 日**上线公测，距离上一版 DeepSeek-V4-Flash 预览版（4 月 24 日）发布，已经过去约 3 个月。\\n\\nDeepSeek-V4-Flash 因为**极低的价格**和**还不错的体验**，成为了国内外公认的**价格屠夫**、香饽饽。它也一直是万少电脑上必备的一个选项。\\n\\n而在正式版发布前的这几个月里，国内顶尖模型也在陆续更新：\\n\\n- **GLM-5.2**（智谱，6 月发布，753B 参数，1M 上下文）\\n- **Kimi K3**（月之暗面，2.8 万亿参数）\\n- **Qwen3.8-Max-Preview**（阿里，7 月发布，2.4 万亿参数）\\n\\n现在 DeepSeek-V4-Flash 正式版出来，万少体验下来，**它又回到了国内模型第一档的层次了**。\\n\\n![](assets/image-20260802121927583.png)\\n\\n---\\n\\n## 主要注意\\n\\n很多朋友可能只在新闻里看到**DeepSeek-V4-Flash 正式版很强**，但一些小细节未必留意到。这里万少就把自己踩过的几个坑，给大家分享一下。\\n\\n---\\n\\n## 1. 一些 AI IDE 和模型聚合厂商，可能还在用预览版\\n\\n虽然名字都叫 `deepseek-v4-flash`，但**最新的才是正式版**！一些模型聚合厂商、AI IDE 集成的，可能还是**预览版**，所以你自己体验下来可能会觉得**能力一般**。\\n\\n![](assets/image-20260802121702176.png)\\n\\n所以如果你想用正式版，**建议官网直连**，这样确保不会出错。\\n\\n![](assets/image-20260802121743303.png)\\n\\n---\\n\\n![](assets/image-20260802121803412.png)\\n\\n---\\n\\n## 2. DeepSeek-V4-Flash 不是多模态\\n\\n可能一些朋友用惯了多模态的模型或 AI 工具，已经习惯把图片、视频等资料直接发给 AI，AI 能识别、解析，就像长了眼睛和耳朵一样，能和你轻松对话。\\n\\n但是 **DeepSeek-V4-Flash 正式版不是多模态的**，它目前**只能接入文本类的输入**。所以小伙伴们如果需要用到多模态能力（识图、看视频等），就需要特别注意了。\\n\\n![](assets/image-20260802122148009.png)\\n\\n---\\n\\n## 3. DeepSeek-V4-Flash 官方没有出包月套餐\\n\\n价格敏感的朋友可能用惯了**包月 / 包年套餐**，这样使用起来起码没有心智负担——冲一次，随便用。\\n\\n但是 **DeepSeek-V4-Flash 正式版没有提供包月套餐**，基本上是**充多少用多少**。所以小伙伴们使用官网直连 DeepSeek-V4-Flash 的时候，尤其需要关注自己的费用，避免出现太大的损失。\\n\\n![](assets/image-20260802122209852.png)\\n\\n## 关于我\\n\\n以上这些建议，是万少使用下来后的一些分享，希望能帮到大家。万少也一直在使用 AI 工具做各种各样的尝试。\\n\\n![](assets/image-20260802120234453.png)\\n\\n---\\n\\n![](assets/image-20260802120257143.png)\\n\\n如果你想进行 AI 的技术交流，欢迎联系我。\\n\\n## 个人官网\\n\\n> https://blog.zbztb.cn/\\n"}'),k={name:"AI人工智能/DeepSeek-V4-Flash 正式版上线了，但这 3 个坑我帮你提前踩了/DeepSeek-V4-Flash 正式版上线了，但这 3 个坑我帮你提前踩了.md"};function c(m,e,d,D,S,V){return a(),n("div",null,[...e[0]||(e[0]=[t("",37)])])}const b=s(k,[["render",c]]);export{I as __pageData,b as default};
